package brick

import (
	"os"
	"path/filepath"
	"regexp"
	"slices"
	"strings"
	"testing"
)

// The component catalog in kit/README.md is generated by
// scripts/kit_catalog.py; catBuild builds the same text in Go so this gate
// needs no Python. The two must stay in step: if one changes, this test
// fails against the README the other wrote.
const (
	catReadme = "kit/README.md"
	catPages  = "examples/ui/content/components"
	catNav    = "examples/ui/data/nav.yaml"
	catStart  = "<!-- catalog:start -->"
	catEnd    = "<!-- catalog:end -->"
	catLink   = "../examples/ui/content/components/"
)

var catKeyRe = regexp.MustCompile(`^(title|category|description):(.*)$`)

// catScalar reads a one-line YAML scalar: plain, "double" (with \" and \\)
// or 'single'.
func catScalar(v string) string {
	v = strings.TrimSpace(v)
	if len(v) >= 2 && v[0] == '"' && v[len(v)-1] == '"' {
		return strings.ReplaceAll(strings.ReplaceAll(v[1:len(v)-1], `\"`, `"`), `\\`, `\`)
	}
	if len(v) >= 2 && v[0] == '\'' && v[len(v)-1] == '\'' {
		return strings.ReplaceAll(v[1:len(v)-1], "''", "'")
	}
	return v
}

// catFrontmatter returns a page's title, category and description.
func catFrontmatter(text string) map[string]string {
	out := map[string]string{}
	if !strings.HasPrefix(text, "---\n") {
		return out
	}
	end := strings.Index(text[4:], "\n---")
	if end < 0 {
		return out
	}
	for line := range strings.SplitSeq(text[4:4+end], "\n") {
		if m := catKeyRe.FindStringSubmatch(line); m != nil {
			out[m[1]] = catScalar(m[2])
		}
	}
	return out
}

// catCategories lists nav.yaml's categories in order.
func catCategories(t *testing.T) []string {
	t.Helper()
	b, err := os.ReadFile(catNav)
	if err != nil {
		t.Fatal(err)
	}
	var out []string
	inside := false
	for line := range strings.SplitSeq(string(b), "\n") {
		switch {
		case strings.HasPrefix(line, "categories:"):
			inside = true
		case inside && strings.HasPrefix(line, "  - "):
			out = append(out, catScalar(line[4:]))
		case inside && line != "" && !strings.HasPrefix(line, " "):
			inside = false
		}
	}
	return out
}

func catCell(s string) string { return strings.ReplaceAll(s, "|", `\|`) }

type catPage struct{ title, file, desc string }

// catBuild is the catalog block, markers included.
func catBuild(t *testing.T) string {
	t.Helper()
	entries, err := os.ReadDir(catPages)
	if err != nil {
		t.Fatal(err)
	}
	pages := map[string][]catPage{}
	for _, e := range entries {
		if !strings.HasSuffix(e.Name(), ".html") {
			continue
		}
		b, err := os.ReadFile(filepath.Join(catPages, e.Name()))
		if err != nil {
			t.Fatal(err)
		}
		fm := catFrontmatter(string(b))
		title, okT := fm["title"]
		cat, okC := fm["category"]
		if okT && okC {
			pages[cat] = append(pages[cat], catPage{title, e.Name(), fm["description"]})
		}
	}
	order := catCategories(t)
	var extra []string
	for c := range pages {
		if !slices.Contains(order, c) {
			extra = append(extra, c)
		}
	}
	slices.Sort(extra)
	order = append(order, extra...)
	lines := []string{catStart, "", "<!-- Generated by scripts/kit_catalog.py from the doc pages' frontmatter; do not edit by hand. -->"}
	for _, c := range order {
		ps, ok := pages[c]
		if !ok {
			continue
		}
		slices.SortFunc(ps, func(a, b catPage) int {
			if x, y := strings.ToLower(a.title), strings.ToLower(b.title); x != y {
				return strings.Compare(x, y)
			}
			return strings.Compare(a.file, b.file)
		})
		lines = append(lines, "", "### "+c, "", "| Component | Description |", "|---|---|")
		for _, p := range ps {
			lines = append(lines, "| ["+catCell(p.title)+"]("+catLink+p.file+") | "+catCell(p.desc)+" |")
		}
	}
	lines = append(lines, "", catEnd)
	return strings.Join(lines, "\n")
}

// The README's catalog matches the doc pages: a new, renamed or
// recategorised page fails here until `task kit:catalog` runs.
func TestKitCatalogIsCurrent(t *testing.T) {
	t.Parallel()
	b, err := os.ReadFile(catReadme)
	if err != nil {
		t.Fatal(err)
	}
	text := string(b)
	a, z := strings.Index(text, catStart), strings.Index(text, catEnd)
	if a < 0 || z < a {
		t.Fatalf("%s has no %s … %s markers", catReadme, catStart, catEnd)
	}
	if got, want := text[a:z+len(catEnd)], catBuild(t); got != want {
		t.Errorf("%s: the component catalog is out of date; run `task kit:catalog` (python3 scripts/kit_catalog.py)", catReadme)
	}
}

// The frontmatter reader handles the three scalar styles the pages use.
func TestKitCatalogScalars(t *testing.T) {
	t.Parallel()
	fm := catFrontmatter("---\ntitle: Card\ncategory: \"Data display\"\ndescription: 'It''s a card: \"boxed\" | framed.'\napi:\n  - {name: x}\n---\n<h1>")
	want := map[string]string{"title": "Card", "category": "Data display", "description": `It's a card: "boxed" | framed.`}
	for k, v := range want {
		if fm[k] != v {
			t.Errorf("%s = %q, want %q", k, fm[k], v)
		}
	}
	if catCell("a | b") != `a \| b` {
		t.Error("a pipe in a cell is not escaped")
	}
}
